using System; using System.Collections.Generic; using NUnit.Framework; using AcadeGameMaker.Costumes;
namespace AcadeGameMaker.Tests.EditMode.Costumes { public sealed class CostumeCoreV1Tests { const string H="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
[Test] public void AC_COST_001_InventoryIsExactAndPending(){var c=CostumeCatalogV1.SeryeongInventoryPending();Assert.That(c.Definitions.Count,Is.EqualTo(36));Assert.That(c.Find("seryeong.costume.h1.v1"),Is.Null);Assert.That(c.Find("seryeong.costume.s1.v1").Disposition,Is.EqualTo(CostumeDisposition.ProductionPending));Assert.That(c.Availability("seryeong"),Is.EqualTo(CostumeAvailability.NoAcceptedDefault));}
[Test] public void AC_COST_002_RejectsUnsortedDuplicateAndDefaults(){var one=A("one",true);Assert.Throws<ArgumentException>(()=>new CostumeCatalogV1(1,new[]{one,one}));Assert.Throws<ArgumentException>(()=>new CostumeCatalogV1(1,new[]{A("two",false),one}));Assert.Throws<ArgumentException>(()=>new CostumeCatalogV1(1,new[]{one,A("two",true)}));}
[Test] public void AC_COST_003_SelectionIsLockedRevisionBoundAndSingleUse(){var c=new CostumeCatalogV1(2,new[]{A("one",true)});var s=new CostumeStateV1(0,new[]{"seryeong.costume.one.v1"},new KeyValuePair<string,string>[0]);var p=CostumeSelectionServiceV1.PrepareSelection(c,s,"seryeong","seryeong.costume.one.v1",0,2);var n=CostumeSelectionServiceV1.Commit(p,c,s);Assert.That(n.Current("seryeong"),Is.EqualTo("seryeong.costume.one.v1"));Assert.Throws<InvalidOperationException>(()=>CostumeSelectionServiceV1.Commit(p,c,s));}
[Test] public void AC_COST_004_CodecIsStableAndTamperRejecting(){var s=new CostumeStateV1(4,new[]{"seryeong.costume.one.v1"},new[]{new KeyValuePair<string,string>("seryeong","seryeong.costume.one.v1")});var a=CostumeCanonicalCodecV1.Encode(s);CollectionAssert.AreEqual(a,CostumeCanonicalCodecV1.Encode(s));Assert.That(CostumeCanonicalCodecV1.TryDecode(a,out var d),Is.True);Assert.That(d.Current("seryeong"),Is.EqualTo(s.Current("seryeong")));a[2]=(byte)'x';Assert.That(CostumeCanonicalCodecV1.TryDecode(a,out _),Is.False);}
static CostumeDefinitionV1 A(string slug,bool def)=>new CostumeDefinitionV1("seryeong","seryeong.costume."+slug+".v1",slug,H,"reference-hair",CostumeDisposition.Accepted,def,"seryeong.costume."+slug+".v1.portrait.v1","seryeong.costume."+slug+".v1.atlas.v1",H,H,H,1);}}
